package com.bnfix.ubm.domains.benefitrequest;
import com.bnfix.ubm.domains.benefitrequest.dto.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;import java.util.List;import org.springframework.http.*;
@RestController@RequestMapping("/benefit-requests")public class BenefitAccessRequestController{private final BenefitAccessRequestService s;public BenefitAccessRequestController(BenefitAccessRequestService s){this.s=s;}private Long c(Jwt j){Object v=j.getClaims().get("companyId");return v instanceof Number n?n.longValue():Long.valueOf(v.toString());}@PostMapping@PreAuthorize("hasRole('USER')")public ResponseEntity<BenefitAccessRequestResponse> request(@Valid@RequestBody CreateBenefitAccessRequest r,@AuthenticationPrincipal Jwt j){return ResponseEntity.status(201).body(s.request(j.getSubject(),r.benefitId()));}@GetMapping("/me")@PreAuthorize("hasRole('USER')")public List<BenefitAccessRequestResponse> mine(@AuthenticationPrincipal Jwt j){return s.mine(j.getSubject());}@GetMapping("/provider")@PreAuthorize("hasRole('MANAGER')")public List<BenefitAccessRequestResponse> pending(@AuthenticationPrincipal Jwt j){return s.pending(j.getSubject(),c(j));}@PutMapping("/{id}/approve")@PreAuthorize("hasRole('MANAGER')")public BenefitAccessRequestResponse approve(@PathVariable Long id,@AuthenticationPrincipal Jwt j){return s.approve(j.getSubject(),c(j),id);}@PutMapping("/{id}/reject")@PreAuthorize("hasRole('MANAGER')")public BenefitAccessRequestResponse reject(@PathVariable Long id,@Valid@RequestBody RejectBenefitAccessRequest r,@AuthenticationPrincipal Jwt j){return s.reject(j.getSubject(),c(j),id,r.reason());}}
